parameters.jsCode:
const raw = $json.output ?? {};
const sourceUrl = $('Nettoyer et tronquer').item.json.url ?? '';

function clean(value) {
  if (Array.isArray(value)) {
    return value
      .map((item) => String(item).trim())
      .filter(Boolean)
      .join('; ');
  }

  return value === null || value === undefined
    ? ''
    : String(value).trim();
}

function normalizeUrl(value) {
  const original = clean(value);

  if (!original) {
    return '';
  }

  const cleanedUrl = original
    .replace(/\\\//g, '/')
    .split('#')[0];

  const questionMarkIndex = cleanedUrl.indexOf('?');

  const base = questionMarkIndex >= 0
    ? cleanedUrl.slice(0, questionMarkIndex)
    : cleanedUrl;

  const query = questionMarkIndex >= 0
    ? cleanedUrl.slice(questionMarkIndex + 1)
    : '';

  const ignoredParameters = new Set([
    'utm_source',
    'utm_medium',
    'utm_campaign',
    'utm_term',
    'utm_content',
    'rcm',
    'skipredirect'
  ]);

  const retainedParameters = query
    .split('&')
    .filter(Boolean)
    .filter((parameter) => {
      let key = parameter.split('=')[0] || '';

      try {
        key = decodeURIComponent(key);
      } catch {
        key = key;
      }

      return !ignoredParameters.has(key.toLowerCase());
    });

  const normalizedBase = base.replace(/\/$/, '');

  return retainedParameters.length
    ? `${normalizedBase}?${retainedParameters.join('&')}`
    : normalizedBase;
}

function slug(value) {
  return clean(value)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function fnv1a(value) {
  let hash = 0x811c9dc5;

  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }

  return (hash >>> 0)
    .toString(16)
    .padStart(8, '0');
}

const entreprise = clean(raw.entreprise);
const poste = clean(raw.poste);
const description = clean(raw.description);
const missions = clean(raw.missions);
const profilCible = clean(raw.profil_cible);
const competencesCles = clean(raw.competences_cles);
const domaine = clean(raw.domaine);
const typeStage = clean(raw.type_stage);

const pays = clean(raw.pays);
const ville = clean(raw.ville);
const modeTravail = clean(raw.mode_travail);

const datePublication = clean(raw.date_publication);
const dateLimite = clean(raw.date_limite);
const dateDebut = clean(raw.date_debut);
const duree = clean(raw.duree);

const remunerationStatus = clean(raw.remuneration_status);
const remunerationAmount = clean(raw.remuneration_amount);
const remunerationCurrency = clean(raw.remuneration_currency);
const remunerationPeriod = clean(raw.remuneration_period);
const remunerationDetails = clean(raw.remuneration_details);
const remunerationEvidence = clean(raw.remuneration_evidence);

const normalizedSourceUrl = normalizeUrl(sourceUrl);
const applicationUrl = normalizeUrl(raw.url_candidature);

const identityParts = [
  entreprise,
  poste,
  ville,
  datePublication
]
  .map(slug)
  .filter(Boolean);

const identityBase = identityParts.length >= 2
  ? identityParts.join('|')
  : applicationUrl || normalizedSourceUrl;

const offerId = `offer_${fnv1a(identityBase)}`;

const urlForDomain = applicationUrl || normalizedSourceUrl;

const domainMatch = urlForDomain.match(
  /^https?:\/\/([^/?#]+)/i
);

const sourceDomain = domainMatch
  ? domainMatch[1]
      .replace(/^www\./i, '')
      .toLowerCase()
  : '';

const completenessValues = [
  entreprise,
  poste,
  description,
  missions,
  profilCible,
  competencesCles,
  domaine,
  pays,
  ville,
  dateLimite,
  duree,
  modeTravail !== 'non_precise'
    ? modeTravail
    : '',
  remunerationStatus !== 'non_precisee'
    ? remunerationStatus
    : ''
];

const completedFields = completenessValues.filter(
  (value) => clean(value)
).length;

const completenessScore = Math.round(
  completedFields / completenessValues.length * 100
);

let extractionStatus = 'nouvelle';

if (clean(raw.is_stage_offer) !== 'oui') {
  extractionStatus = 'rejetee_non_stage';
} else if (clean(raw.etat_offre) === 'fermee') {
  extractionStatus = 'fermee';
} else if (!entreprise || !poste || !pays) {
  extractionStatus = 'a_verifier';
}

const remunerationPriorities = {
  confirmee: 'prioritaire',
  non_precisee: 'a_confirmer',
  non_remuneree: 'faible'
};

const remunerationPriority =
  remunerationPriorities[remunerationStatus]
  ?? 'a_confirmer';

return {
  json: {
    offer_id: offerId,

    is_stage_offer: clean(raw.is_stage_offer),
    etat_offre: clean(raw.etat_offre),

    entreprise,
    poste,
    description,
    missions,
    profil_cible: profilCible,
    competences_cles: competencesCles,
    domaine,
    type_stage: typeStage,

    pays,
    ville,
    mode_travail: modeTravail,

    date_publication: datePublication,
    date_limite: dateLimite,
    date_debut: dateDebut,
    duree,

    remuneration_status: remunerationStatus,
    remuneration_priority: remunerationPriority,
    remuneration_amount: remunerationAmount,
    remuneration_currency: remunerationCurrency,
    remuneration_period: remunerationPeriod,
    remuneration_details: remunerationDetails,
    remuneration_evidence: remunerationEvidence,

    source_url: normalizedSourceUrl,
    url_candidature: applicationUrl,
    source_domain: sourceDomain,
    contact_candidature: clean(
      raw.contact_candidature
    ),

    extraction_notes: clean(raw.extraction_notes),

    completeness_score: completenessScore,
    extraction_status: extractionStatus,
    analysis_status: 'pending',
    trello_status: 'not_created',

    detected_at: new Date().toISOString()
  }
};

const pfePatterns = [
  /\bpfe\b/i,
  /projet\s+de\s+fin\s+d['’]études?/i,
  /stage\s+de\s+fin\s+d['’]études?/i,
  /stages?\s+de\s+fin\s+d['’]études?/i,
  /stagiaires?\s+pfe/i,
];

function decodeHtmlEntities(value) {
  const entities = {
    nbsp: ' ',
    amp: '&',
    quot: '"',
    apos: "'",
    lt: '<',
    gt: '>',
    eacute: 'é',
    egrave: 'è',
    ecirc: 'ê',
    agrave: 'à',
    acirc: 'â',
    ugrave: 'ù',
    ucirc: 'û',
    ocirc: 'ô',
    ccedil: 'ç',
    rsquo: '’',
    laquo: '«',
    raquo: '»',
    hellip: '…',
  };

  return String(value ?? '')
    .replace(/&#x([0-9a-f]+);/gi, (match, hex) => {
      const code = Number.parseInt(hex, 16);
      return Number.isFinite(code) ? String.fromCodePoint(code) : match;
    })
    .replace(/&#(\d+);/g, (match, decimal) => {
      const code = Number.parseInt(decimal, 10);
      return Number.isFinite(code) ? String.fromCodePoint(code) : match;
    })
    .replace(/&([a-z]+);/gi, (match, name) => {
      return entities[name.toLowerCase()] ?? match;
    });
}

function htmlToText(value) {
  return decodeHtmlEntities(
    String(value ?? '')
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(p|div|li|h1|h2|h3|h4|h5|h6|tr)>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function normalizeUrl(value) {
  return String(value ?? '')
    .trim()
    .replace(/\\\//g, '/')
    .split('#')[0]
    .replace(/\/+$/, '');
}

const results = [];
const seenUrls = new Set();

for (const item of $input.all()) {
  const raw = item.json ?? {};

  const title = htmlToText(raw.title);
  const summary = htmlToText(
    raw.contentSnippet ?? raw.description ?? ''
  );

  const searchableText = `${title}\n${summary}`;

  const isPfeOffer = pfePatterns.some((pattern) =>
    pattern.test(searchableText)
  );

  if (!isPfeOffer) {
    continue;
  }

  const url = normalizeUrl(raw.link ?? raw.guid);

  if (!url || seenUrls.has(url)) {
    continue;
  }

  seenUrls.add(url);

  const articleContent = htmlToText(
    raw.content ??
    raw['content:encoded'] ??
    raw.description ??
    ''
  );

  const texte = [
    title ? `Titre : ${title}` : '',
    summary ? `Résumé : ${summary}` : '',
    articleContent
      ? `Contenu de l'annonce :\n${articleContent}`
      : '',
  ]
    .filter(Boolean)
    .join('\n\n')
    .slice(0, 12000);

  results.push({
    json: {
      url,
      texte,
      discovery_source: 'dreamjob',
      discovery_title: title,
      discovery_summary: summary,
      discovery_date: String(
        raw.isoDate ?? raw.pubDate ?? ''
      ).trim(),
    },
  });
}

return results;
